/**
 * Removes the indentation that all non-blank lines share.
 * @param {string} text The indented source text.
 * @returns {string} The source text without the shared indentation.
 */
function stripSharedIndent(text) {
	const lines = text.split("\n");
	const indents = lines
		.filter(line => line.trim() !== "")
		.map(line => line.match(/^\s*/u)[0].length);
	const shared = Math.min(...indents);

	return lines.map(line => line.slice(shared)).join("\n");
}

