		const code = stripSharedIndent(`
			const a = 1;
			const b = [
			    a,
			    missing
			];
		`);
		const [message] = linter.verify(code, config);

		assert.strictEqual(message.ruleId, "no-undef");
		assert.strictEqual(message.line, 5);
		assert.strictEqual(message.column, 5);
