/**
 * Removes the indentation that all non-blank lines share, and a leading newline.
 * @param {string} text Indented template literal text.
 * @returns {string} The text with its common indentation removed.
 */
function dedent(text) {
	const lines = text.replace(/^\n/u, "").split("\n");
	const indent = Math.min(
		...lines
			.filter(line => line.trim() !== "")
			.map(line => line.match(/^\s*/u)[0].length),
	);

	return lines.map(line => line.slice(indent)).join("\n");
}

