		rules: {
			"no-undef": "error",
		},
	};

	it("should report no-undef on the line and column of an undefined name", () => {
		const source = dedent(`
			var total = 0;
			var items = [1, 2];
			for (const item of items) {
				total += item * unknownFactor;
			}
		`);
		const messages = linter.verify(source, config);

		assert.strictEqual(messages.length, 1);
		assert.strictEqual(messages[0].ruleId, "no-undef");
		assert.strictEqual(messages[0].line, 4);
