 * indentation shared by all non-blank lines of a template literal.
 * @param {string} text The indented source text.
 * @returns {string} The source text as it would appear unindented.
 */
function unindent(text) {
	const lines = text
		.replace(/^\r?\n/u, "")
		.replace(/\r?\n[\t ]*$/u, "")
		.split(/\r?\n/u);
