		.filter(line => line.trim())
		.map(line => /^[\t ]*/u.exec(line)[0]);
	const common = indents.reduce((prefix, indent) => {
		let i = 0;

		while (i < prefix.length && prefix[i] === indent[i]) {
			i++;
		}
		return prefix.slice(0, i);
	}, indents[0] ?? "");

	return lines
		.map(line =>
			line.startsWith(common)
				? line.slice(common.length)
				: line.trimStart(),
		)
		.join("\n");
}

