 * whitespace (tabs or spaces) shared by all non-blank lines.
 * @param {string} text The indented source text.
 * @returns {string} The source text without shared indentation.
 */
function stripIndent(text) {
	const lines = text
		.replace(/^\n/u, "")
		.replace(/\n[\t ]*$/u, "")
		.split("\n");
	const indents = lines
		.filter(line => line.trim())
		.map(line => line.match(/^[\t ]*/u)[0]);
	const shared = indents.reduce((prefix, indent) => {
		let i = 0;

		while (i < prefix.length && prefix[i] === indent[i]) {
			i++;
		}

		return prefix.slice(0, i);
	});

	return lines.map(line => line.slice(shared.length)).join("\n");
}

